import { cache } from 'react'
import { createClient } from '@/lib/supabase/server'
import type { Database } from '@/lib/supabase/types'

export type UserPinnedItem = Database['public']['Tables']['user_pinned_items']['Row']
export type PinnedItemKind = UserPinnedItem['kind']

/**
 * Fetch all pinned items for a user+studio pair.
 * Wrapped in React cache() so repeated calls within the same render tree
 * (layout + page) are deduplicated — one round-trip per request.
 */
export const fetchUserPins = cache(async (
  userId: string,
  studioId: string,
): Promise<UserPinnedItem[]> => {
  const supabase = await createClient()
  const { data, error } = await supabase
    .from('user_pinned_items')
    .select('*')
    .eq('user_id', userId)
    .eq('studio_id', studioId)
    .order('sort_order', { ascending: true })
    .limit(50)

  if (error) return []
  return data ?? []
})

/**
 * Check whether a specific item is pinned.
 * Delegates to fetchUserPins (also cached) — no extra query.
 */
export async function isPinned(
  userId: string,
  studioId: string,
  kind: PinnedItemKind,
  target: string,
): Promise<boolean> {
  const pins = await fetchUserPins(userId, studioId)
  return pins.some((p) => p.kind === kind && p.target === target)
}

'use server'

import { revalidatePath } from 'next/cache'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio } from '@/lib/context/active-studio'
import type { PinnedItemKind } from '@/lib/pinned-items/pinned'

const MAX_PINS = 50

interface PinPayload {
  kind: PinnedItemKind
  target: string
  label: string
  href: string
  icon?: string | null
}

async function getAuthContext() {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) throw new Error('Unauthenticated')

  const { studioId } = await getActiveStudio()
  return { supabase, userId: user.id, studioId }
}

export async function pinItemAction(payload: PinPayload): Promise<void> {
  const { supabase, userId, studioId } = await getAuthContext()

  // Enforce max 50 pins per user/studio
  const { count } = await supabase
    .from('user_pinned_items')
    .select('id', { count: 'exact', head: true })
    .eq('user_id', userId)
    .eq('studio_id', studioId)

  if ((count ?? 0) >= MAX_PINS) {
    throw new Error(`Pin limit reached (max ${MAX_PINS})`)
  }

  // Idempotent: upsert on (user_id, studio_id, kind, target)
  const { error } = await supabase
    .from('user_pinned_items')
    .upsert(
      {
        user_id: userId,
        studio_id: studioId,
        kind: payload.kind,
        target: payload.target,
        label: payload.label,
        href: payload.href,
        icon: payload.icon ?? null,
        sort_order: count ?? 0,
      },
      { onConflict: 'user_id,studio_id,kind,target', ignoreDuplicates: false },
    )

  if (error) throw new Error(error.message)
  revalidatePath('/', 'layout')
}

export async function unpinItemAction(payload: Pick<PinPayload, 'kind' | 'target'>): Promise<void> {
  const { supabase, userId, studioId } = await getAuthContext()

  const { error } = await supabase
    .from('user_pinned_items')
    .delete()
    .eq('user_id', userId)
    .eq('studio_id', studioId)
    .eq('kind', payload.kind)
    .eq('target', payload.target)

  if (error) throw new Error(error.message)
  revalidatePath('/', 'layout')
}

export async function reorderPinsAction(orderedIds: string[]): Promise<void> {
  const { supabase, userId, studioId } = await getAuthContext()

  // Verify all ids belong to this user+studio before updating
  const { data: existing } = await supabase
    .from('user_pinned_items')
    .select('id')
    .eq('user_id', userId)
    .eq('studio_id', studioId)

  const ownedIds = new Set((existing ?? []).map((r) => r.id))
  const allOwned = orderedIds.every((id) => ownedIds.has(id))
  if (!allOwned) throw new Error('Unauthorized pin reorder')

  await Promise.all(
    orderedIds.map((id, index) =>
      supabase
        .from('user_pinned_items')
        .update({ sort_order: index })
        .eq('id', id)
        .eq('user_id', userId)
        .eq('studio_id', studioId),
    ),
  )

  revalidatePath('/', 'layout')
}

'use client'

import { useOptimistic, useTransition } from 'react'
import { Star } from 'lucide-react'
import { toast } from 'sonner'
import { pinItemAction, unpinItemAction } from '@/app/actions/pinned-items'
import { cn } from '@/lib/utils'
import type { PinnedItemKind } from '@/lib/pinned-items/pinned'

interface PinButtonProps {
  kind: PinnedItemKind
  target: string
  label: string
  href: string
  icon?: string | null
  isPinned: boolean
  className?: string
}

export function PinButton({
  kind,
  target,
  label,
  href,
  icon,
  isPinned,
  className,
}: PinButtonProps) {
  const [optimisticPinned, setOptimisticPinned] = useOptimistic(isPinned)
  const [pending, startTransition] = useTransition()

  function handleToggle(e: React.MouseEvent) {
    e.preventDefault()
    e.stopPropagation()

    startTransition(async () => {
      const next = !optimisticPinned
      setOptimisticPinned(next)
      try {
        if (next) {
          await pinItemAction({ kind, target, label, href, icon: icon ?? null })
          toast.success(`Pinned "${label}"`)
        } else {
          await unpinItemAction({ kind, target })
          toast.success(`Unpinned "${label}"`)
        }
      } catch (err) {
        setOptimisticPinned(!next)
        toast.error(err instanceof Error ? err.message : 'Failed to update pin')
      }
    })
  }

  return (
    <button
      type="button"
      aria-label={optimisticPinned ? `Unpin ${label}` : `Pin ${label}`}
      aria-pressed={optimisticPinned}
      onClick={handleToggle}
      disabled={pending}
      className={cn(
        'inline-flex items-center justify-center rounded-md p-1 transition-colors',
        'text-muted-foreground/40 hover:text-amber-500 hover:bg-amber-500/10',
        optimisticPinned && 'text-amber-500',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
        className,
      )}
    >
      <Star
        className="h-3.5 w-3.5"
        fill={optimisticPinned ? 'currentColor' : 'none'}
        aria-hidden="true"
      />
    </button>
  )
}

