  params: Promise<{ id: string }>
}

/**
 * S22: Thin server wrapper — resolves isPinned server-side, passes it to
 * the existing client component so PinButton renders with the correct
 * initial state without any client-side fetch.
 */
export default async function ArtistDetailPage({ params }: Props) {
  const { id } = await params

  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const artistIsPinned = await checkIsPinned(auth.user.authId, auth.studioId, 'artist', id)

  return <ArtistDetailClient params={params} isPinnedInitial={artistIsPinned} />
}

